state"><strong>No metered usage yet.</strong>Usage events appear here after workflows, agents and provider actions execute.</div>}</article></section><section className="table-panel" style={{marginTop:14}}><div className="table-top"><h2>Plans</h2><small>Server-controlled Stripe price mapping</small></div><div className="table-scroll"><table className="data-table"><thead><tr><th>PLAN</th><th>USERS</th><th>AGENTS</th><th>INTEGRATIONS</th><th>WORKFLOWS / MO</th><th>ACTION</th></tr></thead><tbody>{Object.entries(plans).map(([id,p])=><tr key={id}><td><strong>{id.charAt(0).toUpperCase()+id.slice(1)}</strong></td><td>{p.maxUsers}</td><td>{p.maxAgents}</td><td>{p.maxIntegrations}</td><td>{p.maxWorkflowRunsMonthly}</td><td>{id===current?<span className="state good">Current</span>:canManage&&stripeReady?<form method="post" action={billing?.subscriptionRef?"/api/billing/plan":"/api/billing/checkout"}><input type="hidden" name="plan" value={id}/><button className="action-chip">{billing?.subscriptionRef?"Change plan":"Choose plan"}</button></form>:<span className="state">Read only</span>}</td></tr>)}</tbody></table></div></section></>;
